public interface MessageSender {
    void send(String message);
}

@Component
@Primary
public class EmailMessageSender implements MessageSender {
    @Override
    public void send(String message) {
        System.out.println("Sending Email: " + message);
    }
}

@Component
@Qualifier("smsSender")
public class SmsMessageSender implements MessageSender {
    @Override
    public void send(String message) {
        System.out.println(
            "Sending SMS: " + message);
    }
}

@Component
public class NotificationService {
    private final MessageSender defaultSender;
    private final MessageSender smsSender;

    public NotificationService(
            MessageSender defaultSender,
            @Qualifier("smsSender") MessageSender smsSender) {
        this.defaultSender = defaultSender; // Resolves to EmailMessageSender via @Primary
        this.smsSender = smsSender;         // Resolves to SmsMessageSender via @Qualifier
    }
}
